CREATE TYPE "ProjectStatus" AS ENUM ('IDEA', 'IN_PROGRESS', 'COMPLETED');
CREATE TYPE "RequestStatus" AS ENUM ('PENDING', 'ACCEPTED', 'REJECTED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "college" TEXT NOT NULL, "state" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "tech" TEXT[], "githubUrl" TEXT, "status" "ProjectStatus" NOT NULL DEFAULT 'IDEA', "teamSize" INTEGER NOT NULL DEFAULT 1, "lookingFor" TEXT, "isDemo" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "ownerId" TEXT NOT NULL, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CollabRequest" ("id" TEXT NOT NULL, "message" TEXT, "status" "RequestStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "projectId" TEXT NOT NULL, "fromUserId" TEXT NOT NULL, CONSTRAINT "CollabRequest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "Project_status_idx" ON "Project"("status"); CREATE INDEX "Project_ownerId_idx" ON "Project"("ownerId"); CREATE INDEX "Project_createdAt_idx" ON "Project"("createdAt"); CREATE UNIQUE INDEX "CollabRequest_projectId_fromUserId_key" ON "CollabRequest"("projectId", "fromUserId"); CREATE INDEX "CollabRequest_fromUserId_idx" ON "CollabRequest"("fromUserId");
ALTER TABLE "Project" ADD CONSTRAINT "Project_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CollabRequest" ADD CONSTRAINT "CollabRequest_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CollabRequest" ADD CONSTRAINT "CollabRequest_fromUserId_fkey" FOREIGN KEY ("fromUserId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
